<?php
$acr_fields=[];
foreach (['van','naar'] as $acr_key) {
    $acr_raw=$_POST[$acr_key]??'';
    $acr_fields[$acr_key]=is_string($acr_raw)?trim($acr_raw):'';
}
$acr_original_message=$_POST['bericht']??null;
if ($_SERVER['REQUEST_METHOD']==='POST' && is_string($acr_original_message)) {
    if ($acr_fields['van']==='' || $acr_fields['naar']==='') {
        $_POST['bericht']='';
    } else {
        $_POST['bericht']="Ophalen: ".$acr_fields['van']."\nAfleveren: ".$acr_fields['naar']."\n\n".$acr_original_message;
    }
}
require __DIR__.'/_source/source/mail-handler.php';
if (!$sent && is_string($acr_original_message)) { $values['bericht']=$acr_original_message; }
